SELECT NOT EXISTS(SELECT 1 FROM core_import_rows WHERE import_id=$1 AND(operation_date<$2::date OR operation_date>$3::date)) AND EXISTS(SELECT 1 FROM core_balances WHERE company_id=$4 AND account_id=$5 AND balance_date=$6::date AND amount_minor=$7 AND source_kind='statement_eod' AND source_system='dataset_v1' AND source_company_id=$8) AND NOT EXISTS(SELECT 1 FROM unnest($9::bigint[]) wanted(row_number) WHERE NOT EXISTS(SELECT 1 FROM core_import_rows s WHERE s.import_id=$1 AND s.row_number=wanted.row_number AND s.operation_date=$6::date AND s.balance_minor=$7)) AND NOT EXISTS(SELECT 1 FROM core_transactions t WHERE t.company_id=$4 AND t.account_id=$5 AND t.operation_date BETWEEN $2::date AND $3::date AND NOT EXISTS(SELECT 1 FROM core_import_rows s WHERE s.import_id=$1 AND s.external_id=t.external_id AND s.operation_date=t.operation_date AND s.amount_minor=t.amount_minor AND s.direction=t.direction AND s.payload->>'INN'=t.counterparty_inn AND s.payload->>'Name'=t.counterparty_name AND s.payload->>'Purpose'=t.purpose AND t.source_kind='imported' AND t.source_system='dataset_v1' AND t.source_company_id=$8)) AND NOT EXISTS(SELECT 1 FROM core_balances b WHERE b.company_id=$4 AND b.account_id=$5 AND b.balance_date BETWEEN $2::date AND $3::date AND (b.source_kind<>'statement_eod' OR b.source_system IS DISTINCT FROM 'dataset_v1' OR b.source_company_id IS DISTINCT FROM $8 OR NOT EXISTS(SELECT 1 FROM core_import_rows s WHERE s.import_id=$1 AND s.operation_date=b.balance_date AND s.balance_minor=b.amount_minor)));
